---@class SMonsterListener
local MonsterListener = {}
---@type BattleFormula
local BattleFormula = T(Global, "BattleFormula")

function MonsterListener:init()
    print("MonsterListener:init")
    CEvents.CreatureAttackPlayerEvent:registerCallBack(self.onCreatureAttackPlayer)
    CEvents.PlayerAttackCreatureEvent:registerCallBack(self.onPlayerAttackCreature)
end

function MonsterListener.onCreatureAttackPlayer(targetId, monsterId)
    local player = PlayerManager:getPlayerByEntityId(targetId)
    if not player then
        return false
    end
    ---@type SEntityMonster
    local monster = EntityCache:getEntity(monsterId)
    if not monster then
        return false
    end
    return monster:tryAttackPlayer(player)
end

function MonsterListener.onPlayerAttackCreature(rakssid, entityId, attackType, position)
    local player = PlayerManager:getPlayerByRakssid(rakssid)
    print("onPlayerAttackCreature", rakssid, entityId, attackType, position)
    if not player then
        return false
    end
    if player.battle:isBanAttack() then
        return false
    end
    ---@type SEntityMonster
    local monster = EntityCache:getEntity(entityId)
    if not monster then
        return false
    end
    if monster:inHurtCd(player.userId) then
        return false
    end
    -- local extra = { damage = 0 }
    -- player.battle:setValue(Define.BattleInfoKey.AttackTarget, monster.entityId)
    -- player.battle:onAttack(attackType == 1 and 80 or 250)
    monster:recordHurtCd(player.userId, attackType == 1 and 80 or 250)
    local damage = monster:getAttack()
    local multi = math.max(1, math.min(3, player.battle:getValue(Define.BattleInfoKey.MultiDamage)))
    local result = false
    if multi > 1 then
        result = monster:onPlayerAttacked(player, damage, position) or result
        result = monster:onPlayerAttacked(player, damage * (multi - 1), position) or result
    else
        result = monster:onPlayerAttacked(player, damage, position)
    end
    player.battle:setValue(Define.BattleInfoKey.MultiDamage, 1)
    player.cheat:trigger("attack", monster)
    return result
end

MonsterListener:init()

return MonsterListener